package com.punjab.oms.ar.service.finance;
import com.punjab.oms.ar.ArApplication;import com.punjab.oms.ar.base.*;import com.punjab.oms.ar.domain.dto.finance.*;import com.punjab.oms.ar.enums.*;
import org.springframework.boot.test.context.SpringBootTest;import org.springframework.test.context.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.jdbc.core.JdbcTemplate;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfSystemProperty;import java.math.BigDecimal;import java.time.LocalDate;import java.nio.file.*;import java.util.*;
import static org.assertj.core.api.Assertions.*;
/** scripts/test-mysql-void：财务及上游作废完整事务。 @author Punjab */
@SpringBootTest(classes=ArApplication.class,webEnvironment=SpringBootTest.WebEnvironment.NONE) @ActiveProfiles("pre")
@EnabledIfSystemProperty(named="ar.void.real",matches="true") @EnabledIfSystemProperty(named="ar.void.real.commit",matches="true")
class VoidRealTest {
 @DynamicPropertySource static void config(DynamicPropertyRegistry p){p.add("spring.datasource.url",()->"jdbc:mysql://127.0.0.1:13306/oms_ar_test");p.add("spring.datasource.username",()->"oms_ar");p.add("spring.datasource.password",()->System.getenv("AR_TEST_PASSWORD"));}
 @Autowired ReceivableService receivables;@Autowired ReceivableVoidService voids;@Autowired JdbcTemplate jdbc;
 private String key(){return UUID.randomUUID().toString();}private BigDecimal n(String value){return new BigDecimal(value);}
 private void actor(){CurrentUser.set(new CurrentUser.Identity("void-test",Set.of(1L),Set.of("ar:create","ar:void","ar:void:upstream:WMS","ar:read","ar:settle","ar:receipt:create","ar:reverse","ar:invoice:write","ar:balance:transfer")));}
 @BeforeEach void setup()throws Exception{assertThat(jdbc.queryForObject("SELECT DATABASE()",String.class)).isEqualTo("oms_ar_test");for(String name:List.of("V001__ar_core.sql","V002__ar_audit.sql","V011__ar_outbox.sql","V003__ar_receipt.sql","V004__ar_settlement.sql","V005__ar_adjustment_link.sql","V006__ar_customer_balance.sql","V007__ar_balance_settlement.sql","V008__ar_invoice.sql","V009__ar_exchange_basis.sql","V010__ar_source_guard.sql"))for(String sql:Files.readString(Path.of("../scratch/dbddl/"+name)).split(";"))if(!sql.isBlank())jdbc.execute(sql);actor();}
 @AfterEach void clear(){CurrentUser.clear();}
 private ReceivableCreateRequest.Line line(String amount,Long group,Long original,ReceivableCreateRequest.Source source){return new ReceivableCreateRequest.Line("A",group,AmountType.PRINCIPAL,n(amount),null,null,source,original);}
 private long create(ReceivableCreateRequest.Line... lines){return receivables.create(new ReceivableCreateRequest(key(),1L,1L,"CNY","SERVICE",LocalDate.now(),null,"test",List.of(lines)));}
 private long lineId(long doc){return jdbc.queryForObject("SELECT id FROM oms_ar_line WHERE document_id=?",Long.class,doc);}
 private long group(long line){return jdbc.queryForObject("SELECT group_id FROM oms_ar_line WHERE id=?",Long.class,line);}
 private void assertVoid(long line){assertThat(jdbc.queryForObject("SELECT status FROM oms_ar_line WHERE id=?",String.class,line)).isEqualTo("VOID");assertThat(jdbc.queryForObject("SELECT open_amount FROM oms_ar_line WHERE id=?",BigDecimal.class,line)).isEqualByComparingTo("0");}
 private ReceivableCreateRequest.Source source(String id,String line){return new ReceivableCreateRequest.Source("WMS","OUTBOUND",id,id,line,key(),"price");}
 @Test @DisplayName("财务直接作废保留原额并记录完整快照，重复请求不重复变更")void finance(){long doc=create(line("100",null,null,null)),id=lineId(doc);var request=new ReceivableVoidRequest(key(),1L,doc,"录入错误");var response=voids.voidDocument(request);assertThat(response.lineIds()).containsExactly(id);assertThat(voids.voidDocument(request)).isEqualTo(response);assertVoid(id);assertThat(jdbc.queryForObject("SELECT receivable_amount FROM oms_ar_line WHERE id=?",BigDecimal.class,id)).isEqualByComparingTo("100");assertThat(jdbc.queryForObject("SELECT void_reason FROM oms_ar_document WHERE id=?",String.class,doc)).isEqualTo("录入错误");assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM oms_ar_lifecycle_change WHERE event_id=? AND object_type='LINE' AND before_snapshot IS NOT NULL AND after_snapshot IS NOT NULL",Integer.class,response.eventId())).isEqualTo(1);}
 @Test @DisplayName("上游只作废指定来源行，其余来源有效，最后一行取消才作废单头")void partial(){String source=key();long doc=create(line("100",null,null,source(source,"1")),line("50",null,null,source(source,"2")));var ids=jdbc.queryForList("SELECT id FROM oms_ar_line WHERE document_id=? ORDER BY line_no",Long.class,doc);var first=new UpstreamVoidRequest(key(),1L,"WMS",List.of(new UpstreamVoidRequest.Source("OUTBOUND",source,"1")),"取消第一行");var result=voids.voidUpstream(first);assertThat(result.lineIds()).containsExactly(ids.get(0));assertVoid(ids.get(0));assertThat(jdbc.queryForObject("SELECT status FROM oms_ar_document WHERE id=?",String.class,doc)).isEqualTo("ACTIVE");assertThatThrownBy(()->create(line("100",null,null,source(source,"1")))).isInstanceOf(ServiceException.class);voids.voidUpstream(new UpstreamVoidRequest(key(),1L,"WMS",List.of(new UpstreamVoidRequest.Source("OUTBOUND",source,"2")),"取消第二行"));assertThat(jdbc.queryForObject("SELECT status FROM oms_ar_document WHERE id=?",String.class,doc)).isEqualTo("VOID");}
 @Test @DisplayName("来源取消先于生成到达也必须阻止迟到生成")void cancelBeforeCreate(){String source=key();var result=voids.voidUpstream(new UpstreamVoidRequest(key(),1L,"WMS",List.of(new UpstreamVoidRequest.Source("OUTBOUND",source,null)),"取消来源"));assertThat(result.lineIds()).isEmpty();assertThatThrownBy(()->create(line("100",null,null,source(source,null)))).isInstanceOf(ServiceException.class).hasMessageContaining("作废");}
 @Test @DisplayName("有效原行调整不能被作废孤立，先取消调整再取消原行")void adjustment(){long doc=create(line("100",null,null,null)),id=lineId(doc),credit=create(line("-20",null,id,null));assertThatThrownBy(()->voids.voidDocument(new ReceivableVoidRequest(key(),1L,doc,"仍有调整"))).isInstanceOf(ServiceException.class);voids.voidDocument(new ReceivableVoidRequest(key(),1L,credit,"取消调整"));voids.voidDocument(new ReceivableVoidRequest(key(),1L,doc,"取消原应收"));assertVoid(id);}
 @Autowired ReceiptService receipts;@Autowired SettlementService settlements;@Autowired InvoiceService invoices;@Autowired CustomerBalanceService balances;
 private long receipt(){return receipts.create(new ReceiptCreateRequest(key(),1L,1L,"CNY",n("100"),LocalDate.now(),"TEST",key(),"void receipt"));}
 private SettlementConfirmRequest settlement(long line){var request=new SettlementPreviewRequest(1L,receipt(),n("10"),List.of(group(line)),AllocationStrategy.GROUP_TAX_FIRST);return new SettlementConfirmRequest(key(),request,settlements.preview(request).fingerprint(),"test");}
 private InvoiceRegisterRequest invoice(long line){var request=new InvoicePreviewRequest(1L,1L,"CNY",InvoiceKind.BLUE,null,n("10"),List.of(new InvoicePreviewRequest.Line("1",line,n("10"),null,null)));return new InvoiceRegisterRequest(key(),"TEST",key(),key(),LocalDate.now(),request,invoices.preview(request).fingerprint(),"test");}
 private ReceivableVoidRequest cancel(long doc){return new ReceivableVoidRequest(key(),1L,doc,"void test");}
 @Test @DisplayName("核销有效时拒绝作废，反核销后可作废且收款仍可用")void settledDependency(){long doc=create(line("100",null,null,null)),id=lineId(doc);var request=settlement(id);long settled=settlements.confirm(request);assertThatThrownBy(()->voids.voidDocument(cancel(doc))).isInstanceOf(ServiceException.class).hasMessageContaining("关联");settlements.reverse(new SettlementReverseRequest(key(),1L,settled,"undo"));voids.voidDocument(cancel(doc));assertVoid(id);assertThat(jdbc.queryForObject("SELECT allocated_amount FROM oms_ar_receipt WHERE id=?",BigDecimal.class,request.preview().receiptId())).isEqualByComparingTo("0");}
 @Test @DisplayName("开票有效时拒绝作废，撤销关联后可作废")void invoiceDependency(){long doc=create(line("100",null,null,null)),id=lineId(doc),inv=invoices.register(invoice(id));assertThatThrownBy(()->voids.voidDocument(cancel(doc))).isInstanceOf(ServiceException.class);invoices.reverse(new InvoiceReverseRequest(key(),1L,inv,"undo"));voids.voidDocument(cancel(doc));assertVoid(id);}
 @Test @DisplayName("负数余额转入有效时拒绝作废，撤销转入后允许")void transferDependency(){long doc=create(line("-100",null,null,null)),id=lineId(doc),lot=balances.transfer(new BalanceTransferRequest(key(),1L,id,n("20"),0L,"transfer"));assertThatThrownBy(()->voids.voidDocument(cancel(doc))).isInstanceOf(ServiceException.class);balances.reverseTransfer(new BalanceTransferReverseRequest(key(),1L,lot,"undo"));voids.voidDocument(cancel(doc));assertVoid(id);}
 @Test @DisplayName("有权财务无需审批但原因与主体权限必填，上游不能自报别的系统")void permissions(){long doc=create(line("100",null,null,null));assertThatThrownBy(()->voids.voidDocument(new ReceivableVoidRequest(key(),1L,doc," "))).isInstanceOf(ServiceException.class);assertThatThrownBy(()->voids.voidDocument(new ReceivableVoidRequest(key(),2L,doc,"wrong scope"))).isInstanceOf(com.punjab.oms.ar.base.AccessDeniedException.class);CurrentUser.set(new CurrentUser.Identity("upstream",Set.of(1L),Set.of("ar:void:upstream:WMS")));assertThatThrownBy(()->voids.voidDocument(cancel(doc))).isInstanceOf(com.punjab.oms.ar.base.AccessDeniedException.class);assertThatThrownBy(()->voids.voidUpstream(new UpstreamVoidRequest(key(),1L,"ERP",List.of(new UpstreamVoidRequest.Source("ORDER",key(),null)),"fake"))).isInstanceOf(com.punjab.oms.ar.base.AccessDeniedException.class);}
 @Test @DisplayName("作废流水失败时状态、余额、来源拦截及请求全部回滚")void rollback(){String source=key(),reason="FAIL-"+key(),constraint="reject_void_"+key().replace("-","");long doc=create(line("100",null,null,source(source,null))),id=lineId(doc);var request=new ReceivableVoidRequest(key(),1L,doc,reason);jdbc.execute("ALTER TABLE oms_ar_lifecycle_event ADD CONSTRAINT "+constraint+" CHECK(reason IS NULL OR reason<>'"+reason+"')");try{assertThatThrownBy(()->voids.voidDocument(request)).isInstanceOf(RuntimeException.class);assertThat(jdbc.queryForObject("SELECT status FROM oms_ar_document WHERE id=?",String.class,doc)).isEqualTo("ACTIVE");assertThat(jdbc.queryForObject("SELECT open_amount FROM oms_ar_line WHERE id=?",BigDecimal.class,id)).isEqualByComparingTo("100");assertThat(jdbc.queryForObject("SELECT blocked FROM oms_ar_source_guard WHERE source_id=?",Boolean.class,source)).isFalse();assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM oms_ar_operation_request WHERE request_key=?",Integer.class,request.requestKey())).isZero();}finally{jdbc.execute("ALTER TABLE oms_ar_lifecycle_event DROP CHECK "+constraint);}}
 @Test @DisplayName("移除未开票正数不能扩大共享组开票缺口")void groupInvoiceCapacity(){long first=create(line("100",null,null,null)),firstLine=lineId(first),second=create(line("100",group(firstLine),null,null)),secondLine=lineId(second);create(line("-100",group(firstLine),null,null));var request=new InvoicePreviewRequest(1L,1L,"CNY",InvoiceKind.BLUE,null,n("100"),List.of(new InvoicePreviewRequest.Line("1",secondLine,n("100"),null,null)));invoices.register(new InvoiceRegisterRequest(key(),"TEST",key(),key(),LocalDate.now(),request,invoices.preview(request).fingerprint(),"invoice"));assertThatThrownBy(()->voids.voidDocument(cancel(first))).isInstanceOf(ServiceException.class).hasMessageContaining("额度缺口");}
 @Test @DisplayName("同来源跨单原子作废，一个单据存在有效核销时全部不变")void multipleDocuments(){String source=key();long a=create(line("100",null,null,source(source,"1"))),b=create(line("100",null,null,source(source,"1")));long settled=settlements.confirm(settlement(lineId(b)));var request=new UpstreamVoidRequest(key(),1L,"WMS",List.of(new UpstreamVoidRequest.Source("OUTBOUND",source,"1")),"all source");assertThatThrownBy(()->voids.voidUpstream(request)).isInstanceOf(ServiceException.class);assertThat(jdbc.queryForObject("SELECT status FROM oms_ar_document WHERE id=?",String.class,a)).isEqualTo("ACTIVE");settlements.reverse(new SettlementReverseRequest(key(),1L,settled,"undo"));var result=voids.voidUpstream(request);assertThat(result.documentIds()).containsExactlyInAnyOrder(a,b);assertVoid(lineId(a));assertVoid(lineId(b));}
 @Test @DisplayName("新请求重复作废不重复余额变化，同键不同原因拒绝")void repeated(){long doc=create(line("100",null,null,null));var request=cancel(doc);voids.voidDocument(request);assertThat(voids.voidDocument(cancel(doc)).lineIds()).isEmpty();assertThat(jdbc.queryForObject("SELECT version FROM oms_ar_line WHERE document_id=?",Long.class,doc)).isEqualTo(1);assertThatThrownBy(()->voids.voidDocument(new ReceivableVoidRequest(request.requestKey(),1L,doc,"other reason"))).isInstanceOf(ServiceException.class);}
 @Test @DisplayName("作废与收款核销并发只允许一项成功")void settlementRace()throws Exception{long doc=create(line("100",null,null,null)),id=lineId(doc);var request=settlement(id);race(()->{voids.voidDocument(cancel(doc));return true;},()->{settlements.confirm(request);return true;});assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM oms_ar_settlement_allocation a JOIN oms_ar_settlement s ON s.id=a.settlement_id JOIN oms_ar_line l ON l.id=a.positive_line_id WHERE l.id=? AND l.status='VOID' AND s.status='POSTED'",Integer.class,id)).isZero();}
 @Test @DisplayName("作废与开票并发不会出现有效发票指向作废应收")void invoiceRace()throws Exception{long doc=create(line("100",null,null,null)),id=lineId(doc);var request=invoice(id);race(()->{voids.voidDocument(cancel(doc));return true;},()->{invoices.register(request);return true;});assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM oms_ar_invoice_allocation a JOIN oms_ar_invoice h ON h.id=a.invoice_id JOIN oms_ar_line l ON l.id=a.receivable_line_id WHERE l.id=? AND l.status='VOID' AND h.status='ACTIVE'",Integer.class,id)).isZero();}
 private void race(java.util.concurrent.Callable<Boolean> a,java.util.concurrent.Callable<Boolean> b)throws Exception{var start=new java.util.concurrent.CountDownLatch(2);try(var executor=java.util.concurrent.Executors.newFixedThreadPool(2)){var one=executor.submit(()->racer(start,a));var two=executor.submit(()->racer(start,b));assertThat(List.of(one.get(10,java.util.concurrent.TimeUnit.SECONDS),two.get(10,java.util.concurrent.TimeUnit.SECONDS))).containsExactlyInAnyOrder(true,false);}}
 private boolean racer(java.util.concurrent.CountDownLatch start,java.util.concurrent.Callable<Boolean> action)throws Exception{actor();try{start.countDown();if(!start.await(5,java.util.concurrent.TimeUnit.SECONDS))throw new AssertionError("timeout");try{return action.call();}catch(ServiceException expected){return false;}}finally{CurrentUser.clear();}}

 @Test @DisplayName("迟到生成与上游取消竞争后该来源不能留下有效应收")void sourceRace()throws Exception{
  String source=key();var started=new java.util.concurrent.CountDownLatch(2);
  var cancel=new UpstreamVoidRequest(key(),1L,"WMS",List.of(new UpstreamVoidRequest.Source("OUTBOUND",source,null)),"source race");
  try(var executor=java.util.concurrent.Executors.newFixedThreadPool(2)){
   var creation=executor.submit(()->racer(started,()->{create(line("100",null,null,source(source,null)));return true;}));
   var cancellation=executor.submit(()->racer(started,()->{voids.voidUpstream(cancel);return true;}));
   assertThat(cancellation.get(10,java.util.concurrent.TimeUnit.SECONDS)).isTrue();creation.get(10,java.util.concurrent.TimeUnit.SECONDS);
  }
  assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM oms_ar_line l JOIN oms_ar_line_source s ON s.line_id=l.id WHERE s.source_system='WMS' AND s.source_id=? AND l.status='ACTIVE'",Integer.class,source)).isZero();
  assertThatThrownBy(()->create(line("100",null,null,source(source,null)))).isInstanceOf(ServiceException.class);
 }
 @Test @DisplayName("无来源行取消仅匹配NULL，不误取消空值或其他行")void nullSourceSlot(){String source=key();long noLine=create(line("100",null,null,source(source,null))),empty=create(line("100",null,null,source(source,""))),specific=create(line("100",null,null,source(source,"1")));voids.voidUpstream(new UpstreamVoidRequest(key(),1L,"WMS",List.of(new UpstreamVoidRequest.Source("OUTBOUND",source,null)),"null only"));assertVoid(lineId(noLine));assertThat(jdbc.queryForObject("SELECT status FROM oms_ar_document WHERE id=?",String.class,empty)).isEqualTo("ACTIVE");assertThat(jdbc.queryForObject("SELECT status FROM oms_ar_document WHERE id=?",String.class,specific)).isEqualTo("ACTIVE");}

}
